class Solution {
public:
    std::vector<long long> minimumCosts(std::vector<int>& regular, std::vector<int>& express, int expressCost) {
        long long dp_reg = 0;
        long long dp_exp = expressCost;
        int n = regular.size();
        std::vector<long long> ans(n);
        for (int i = 0; i < n; ++i) {
            long long new_reg = std::min(dp_reg + regular[i], dp_exp + regular[i]);
            long long new_exp = std::min(dp_exp + express[i], dp_reg + expressCost + express[i]);
            dp_reg = new_reg;
            dp_exp = new_exp;
            ans[i] = std::min(dp_reg, dp_exp);
        }
        return ans;
    }
};

class Solution {
    public long[] minimumCosts(int[] regular, int[] express, int expressCost) {
        int n = regular.length;
        long dpReg = 0;
        long dpExp = expressCost;
        long[] ans = new long[n];
        for (int i = 0; i < n; ++i) {
            long newReg = Math.min(dpReg + regular[i], dpExp + regular[i]);
            long newExp = Math.min(dpExp + express[i], dpReg + expressCost + express[i]);
            dpReg = newReg;
            dpExp = newExp;
            ans[i] = Math.min(dpReg, dpExp);
        }
        return ans;
    }
}

